lemma exists_cutoff_classUnip {c}
  K : let Γ := Subgroup.map (S.ratToInf.domRestrict (S.classUnip c)) K; ∃ β, Measurable β
    ∧ (∀ y, ∑' u : K, β (S.ratToInf u * y) = 1) ∧ DiscreteTopology Γ ∧ IsCutoff (H := Γ) .count β

